import math

def is_power_of_two(num):
    if num <= 0:
        return None
    return num.bit_length() - 1 if (num & (num - 1) == 0) else None

def check_solution(x, n):
    lhs = x**n + x
    rhs_minus_2 = lhs - 2
    k = is_power_of_two(rhs_minus_2)
    if k is not None:
        return (x, n, k)
    return None

solutions = []

# 1. Check n=3 for odd x > 5 up to x=15
print("--- Checking n=3 ---")
n = 3
odd_x_range = range(7, 16, 2) # 7, 9, 11, 13, 15
print(f"Checking n={n} for odd x in {list(odd_x_range)}:")
for x in odd_x_range:
    solution = check_solution(x, n)
    if solution:
        solutions.append(solution)
        print(f"Found solution: {solution}")
    else:
        print(f"Checked x={x}: No solution.")

# 2. Check n=4 for all x > 4 up to x=10
print("\n--- Checking n=4 ---")
n = 4
x_range = range(5, 11) # 5, 6, 7, 8, 9, 10
print(f"Checking n={n} for x in {list(x_range)}:")
for x in x_range:
    solution = check_solution(x, n)
    if solution:
        solutions.append(solution)
        print(f"Found solution: {solution}")
    else:
        print(f"Checked x={x}: No solution.")

print("\n--- Summary ---")
if solutions:
    print(f"All candidate solutions found in the specified ranges: {solutions}")
else:
    print("No candidate solutions found in the specified ranges.")

def check_n3(m):
    x = 2 * m
    lhs = x**3 + x

    # We need lhs = 2^k + 2, so 2^k = lhs - 2
    target_power = lhs - 2

    if target_power <= 0:
        return None

    k_minus_1 = target_power.bit_length() - 1
    power_of_2 = 1 << k_minus_1

    if power_of_2 == target_power:
        k = k_minus_1 + 1
        return (x, 3, k)
    else:
        return None

m_values = [3, 4, 5, 6]
results = {}
for m in m_values:
    result = check_n3(m)
    results[m] = result

print(results)

def is_power_of_two(n):
    return n > 0 and (n & (n - 1) == 0)

# Test Candidate B: n=3, checking x >= 7
max_x = 30
solutions_found = []

for x in range(7, max_x + 1):
    f_x = x**3 + x - 2
    if is_power_of_two(f_x):
        k = f_x.bit_length() - 1
        solutions_found.append((x, k))
        print(f"Found solution for x={x}: f(x) = {f_x} = 2^{k}")

if not solutions_found:
    print("No solutions found for n=3, x >= 7 up to x=30.")
else:
    print(f"Solutions found: {solutions_found}")

